\title{Sheaf-Theoretic Data Integration: When Databases Form a Sheaf}
\author{Aristotle}
\date{June 19, 2026}

\begin{document}
\begin{abstract}
We develop a discrete sheaf-theoretic model of database integration and
imputation. A database with missing entries is a \emph{partial section} of the
sheaf of $V$-valued functions on a grid of $(\text{row},\text{column})$
positions. The sheaf condition---pairwise agreement of local views on their
overlaps---is exactly the consistency condition under which partial views glue
into a complete database. We prove that gluing preserves all observed data, is
compatible with incremental integration, and only enlarges the observed
domain. We introduce a discrete coboundary norm counting overlap conflicts and
prove it vanishes iff the sheaf condition holds---the finite analogue of
$\ker\delta^0 = H^0$. We formalize sheaf imputation as minimization of an
observation-fidelity objective and characterize its zero-cost solutions as
exactly the faithful completions. We model the chance that a random noisy
database is consistent as $(1-r)^C$, prove its multiplicativity, monotonicity,
and boundary behavior, and combine it with a quadratic lower bound on the
constraint count to obtain a testable exponential-decay conjecture. Finally we
introduce \emph{sheaf filtrations}, proving that monotonicity forces
consistency and that information accumulates. All results are formalized and
machine-checked.
\end{abstract}

\maketitle

\section{Introduction}
Imputation---filling missing entries of a data table---is ubiquitous. The
dominant methods (mean, $k$-nearest-neighbors, MICE) are pointwise
plausibility heuristics; none treats global consistency as a first-class
constraint. We take the view that the natural consistency structure on a
database is that of a \emph{sheaf}: local data assemble into global data subject
to agreement on overlaps, the gluing axiom (sheaf condition) stating when local
sections determine a unique global section. A database with missing entries is a
partial section of the function sheaf on its cell grid, and consistent
imputation is the search for a global section restricting to the observations.

\medskip\noindent Contributions, each formalized: (i) a discrete model with
basic gluing guarantees (\S3); (ii) an equivalence between a discrete coboundary
norm and the sheaf condition (\S4); (iii) an imputation objective whose zero set
is the faithful completions (\S5); (iv) a consistency-probability calculus
$(1-r)^C$ with a quadratic constraint bound yielding a testable conjecture
(\S6); (v) \emph{sheaf filtrations} with automatic consistency and information
accumulation (\S7).

\section{Definitions}
Fix $\mathit{nRows},\mathit{nCols}\in\mathbb{N}$ and a value type $V$.

\begin{definition}[Position, \texttt{DBPos}]
A \emph{position} is a grid cell
$\mathrm{DBPos}\,\mathit{nRows}\,\mathit{nCols} :=
\mathrm{Fin}\,\mathit{nRows}\times\mathrm{Fin}\,\mathit{nCols}$.
\end{definition}

\begin{definition}[Partial database, \texttt{PartialDB}]
A \emph{partial database} is a function
$\mathrm{DBPos}\to\Opt\,V$; $\none$ denotes a missing entry, $\some\,v$ an
observed value.
\end{definition}

\begin{definition}[Domain, \texttt{PartialDB.dom}]
$\dom(db) := \{p \mid db\,p \neq \none\}$.
\end{definition}

\begin{definition}[Global section, \texttt{IsGlobalSection}]
$db$ is a \emph{global section} iff $\forall p,\ db\,p\neq\none$.
\end{definition}

\begin{definition}[Consistent pair, \texttt{ConsistentPair}]
$db_1,db_2$ form a \emph{consistent pair} iff
$\forall p\,v_1\,v_2,\ db_1\,p=\some\,v_1 \to db_2\,p=\some\,v_2 \to v_1=v_2$.
\end{definition}

\begin{definition}[Sheaf condition, \texttt{SheafCondition}]
A family $\{db_i\}_{i\in\iota}$ satisfies the \emph{sheaf condition} iff
$\forall i\,j,\ \mathrm{ConsistentPair}(db_i,db_j)$.
\end{definition}

\begin{definition}[Gluing, \texttt{GluingMap}]
$\mathrm{GluingMap}\,db_1\,db_2\,p = \some\,v$ if $db_1\,p=\some\,v$, else
$db_2\,p$.
\end{definition}

\begin{definition}[Restriction, \texttt{PartialDB.restrict}]
For decidable $S$, $(db{\restriction}S)\,p = db\,p$ if $p\in S$ else $\none$.
\end{definition}

\begin{definition}[Disagreement indicator, \texttt{disagreementAt}]
With $[\mathrm{DecidableEq}\,V]$,
$\mathrm{disagreementAt}\,db_1\,db_2\,p = 1$ if $db_1\,p=\some\,v_1$,
$db_2\,p=\some\,v_2$, $v_1\neq v_2$, and $0$ otherwise.
\end{definition}

\begin{definition}[Coboundary norm, \texttt{CoboundaryNorm}]
For $dbs:\mathrm{Fin}\,n\to\mathrm{PartialDB}$,
\[
\mathrm{CoboundaryNorm}\,dbs = \sum_{i,j}\sum_{r,c}
\mathrm{disagreementAt}\,(dbs\,i)\,(dbs\,j)\,(r,c),
\]
the discrete analogue of $\lVert\delta^0\sigma\rVert_1$.
\end{definition}

\begin{definition}[Overlap constraint count, \texttt{overlapConstraintCount}]
$\mathrm{overlapConstraintCount}\,n\,\mathit{nRows}\,\mathit{nCols}
= \tfrac{n(n-1)}{2}\cdot(\mathit{nRows}\cdot\mathit{nCols})$.
\end{definition}

\begin{definition}[Consistency probability, \texttt{consistencyProbability}]
For $r\in\mathbb{R}$ and $c\in\mathbb{N}$,
$\mathrm{consistencyProbability}\,r\,c = (1-r)^{c}$.
\end{definition}

\begin{definition}[Imputation objective, \texttt{SheafImputationObjective}]
For observed $db$ and candidate $g:\mathrm{DBPos}\to V$,
\[
\mathrm{SheafImputationObjective}\,db\,g = \sum_{r,c}
\begin{cases}
[\,v\neq g(r,c)\,] & db(r,c)=\some\,v,\\ 0 & db(r,c)=\none.
\end{cases}
\]
\end{definition}

\begin{definition}[Local extension, \texttt{LocallyExtends}]
$db_{\mathrm{ext}}$ \emph{locally extends} $db$ iff it agrees with $db$ on all
defined positions and fills at least one position $db$ leaves blank.
\end{definition}

\begin{definition}[Sheaf filtration, \texttt{SheafFiltration}]
A \emph{sheaf filtration} of depth $d$ comprises a family
$\mathrm{level}:\mathrm{Fin}\,d\to\mathrm{PartialDB}$, a monotonicity law
$\forall i\le j,\forall p\,v,\ \mathrm{level}\,i\,p=\some\,v \to
\mathrm{level}\,j\,p=\some\,v$, and a consistency law
$\mathrm{SheafCondition}(\mathrm{level})$. It is \emph{complete}
(\texttt{isComplete}) when the final level is a global section.
\end{definition}

\section{Gluing and Consistency}

\begin{theorem}[\texttt{consistent\_pair\_symm}]
If $\mathrm{ConsistentPair}\,db_1\,db_2$ then $\mathrm{ConsistentPair}\,db_2\,db_1$.
\end{theorem}
\begin{proof}
Swap witnesses and apply symmetry of $=$ on $V$.
\end{proof}

\begin{theorem}[\texttt{consistent\_pair\_refl}, \texttt{consistent\_with\_empty}]
$\mathrm{ConsistentPair}\,db\,db$ for all $db$; and $\lambda\_.\,\none$ is
consistent with every $db$.
\end{theorem}
\begin{proof}
Reflexivity: $db\,p=\some\,v_1$ and $db\,p=\some\,v_2$ give $v_1=v_2$ by
injectivity of $\some$. Empty: $\none=\some\,v_1$ is absurd.
\end{proof}

\begin{lemma}[\texttt{gluing\_extends\_left}, \texttt{gluing\_extends\_right}]
If $db_1\,p=\some\,v$ then $\mathrm{GluingMap}\,db_1\,db_2\,p=\some\,v$; if
$db_1\,p=\none$ then $\mathrm{GluingMap}\,db_1\,db_2\,p = db_2\,p$.
\end{lemma}

\begin{theorem}[\texttt{gluing\_extends\_both}]
If $\mathrm{ConsistentPair}\,db_1\,db_2$, then for all $p,v$:
$db_1\,p=\some\,v \Rightarrow \mathrm{GluingMap}\,db_1\,db_2\,p=\some\,v$, and
$db_2\,p=\some\,v \Rightarrow \mathrm{GluingMap}\,db_1\,db_2\,p=\some\,v$.
\end{theorem}
\begin{proof}
The left case is the lemma. For the right case, split on $db_1\,p$: if
$\some\,v_1$, consistency gives $v_1=v$; if $\none$, the glue returns
$db_2\,p=\some\,v$.
\end{proof}

\begin{theorem}[\texttt{gluing\_preserves\_consistency}]
If $db_1,db_2,db_3$ are pairwise consistent then
$\mathrm{ConsistentPair}(\mathrm{GluingMap}\,db_1\,db_2)\,db_3$.
\end{theorem}
\begin{proof}
With $(\mathrm{GluingMap}\,db_1\,db_2)\,p=\some\,v_1$ and $db_3\,p=\some\,v_2$,
split on $db_1\,p$: if $\some\,v$, then $v_1=v$ and consistency of $(db_1,db_3)$
gives $v=v_2$; if $\none$, $v_1$ comes from $db_2$ and consistency of
$(db_2,db_3)$ gives $v_1=v_2$.
\end{proof}

\begin{corollary}
A pairwise-consistent finite family glues in any order without conflict.
\end{corollary}

\begin{theorem}[\texttt{gluing\_increases\_domain}, \texttt{gluing\_preserves\_right\_domain}]
$\dom(db_1)\subseteq\dom(\mathrm{GluingMap}\,db_1\,db_2)$ and
$\dom(db_2)\subseteq\dom(\mathrm{GluingMap}\,db_1\,db_2)$.
\end{theorem}

\begin{theorem}[\texttt{gluing\_locally\_extends\_of\_not\_contained}]
If $db_1,db_2$ are consistent and $db_2$ fills a position $db_1$ leaves blank,
then $\mathrm{GluingMap}\,db_1\,db_2$ locally extends $db_1$.
\end{theorem}

\begin{theorem}[\texttt{sheaf\_condition\_of\_global\_restriction}]
For any $g$ and $S:\iota\to\mathrm{Set}(\mathrm{DBPos})$, the family
$\lambda i.\,g{\restriction}(S\,i)$ satisfies the sheaf condition.
\end{theorem}
\begin{proof}
Where two restrictions are both defined, both equal $g\,p$.
\end{proof}

\section{The Coboundary--Sheaf Equivalence}

\begin{theorem}[\texttt{coboundary\_zero\_iff\_sheaf}]
For $dbs:\mathrm{Fin}\,n\to\mathrm{PartialDB}$ with $[\mathrm{DecidableEq}\,V]$,
\[
\mathrm{CoboundaryNorm}\,dbs = 0 \iff \mathrm{SheafCondition}\,dbs.
\]
\end{theorem}
\begin{proof}
A finite sum of naturals is zero iff each summand is zero. Peeling the nested
sums, the norm is zero iff every $\mathrm{disagreementAt}\,(dbs\,i)(dbs\,j)(r,c)$
vanishes, i.e. no two views fill a cell with distinct values---exactly the
sheaf condition. The converse kills each summand.
\end{proof}

\begin{remark}
This is the finite shadow of $\ker\delta^0 = H^0$: the family glues to a global
section iff the conflict count vanishes. Mean/KNN never evaluate this functional.
\end{remark}

\section{Sheaf Imputation as Optimization}

\begin{theorem}[\texttt{imputation\_zero\_iff\_extends}]
For observed $db$ and candidate $g$,
\[
\mathrm{SheafImputationObjective}\,db\,g = 0 \iff
\forall p\,v,\ db\,p=\some\,v \to g\,p=v.
\]
\end{theorem}
\begin{proof}
Sum of naturals is zero iff each summand is zero; at an observed cell the
summand vanishes iff $g$ matches the observation, at a blank it always
vanishes.
\end{proof}

\section{The Consistency-Probability Calculus}

\begin{theorem}[\texttt{consistency\_prob\_mul}]
$\mathrm{consistencyProbability}\,r\,(c_1+c_2) =
\mathrm{consistencyProbability}\,r\,c_1 \cdot
\mathrm{consistencyProbability}\,r\,c_2$.
\end{theorem}
\begin{proof}
$(1-r)^{c_1+c_2}=(1-r)^{c_1}(1-r)^{c_2}$.
\end{proof}

\begin{corollary}[\texttt{consistency\_prob\_double}]
$\mathrm{consistencyProbability}\,r\,(2c) =
(\mathrm{consistencyProbability}\,r\,c)^2$.
\end{corollary}

\begin{theorem}[\texttt{consistency\_prob\_mono\_constraints}]
For $0\le r\le 1$ and $c_1\le c_2$,
$\mathrm{consistencyProbability}\,r\,c_2 \le
\mathrm{consistencyProbability}\,r\,c_1$.
\end{theorem}

\begin{theorem}[\texttt{consistency\_prob\_mono\_rate}]
For $r_2\le 1$ and $r_1\le r_2$,
$\mathrm{consistencyProbability}\,r_2\,c \le
\mathrm{consistencyProbability}\,r_1\,c$.
\end{theorem}

\begin{theorem}[boundary values and range]
$\mathrm{consistencyProbability}\,0\,c=1$
(\texttt{consistency\_prob\_zero\_rate});
for $c>0$, $\mathrm{consistencyProbability}\,1\,c=0$
(\texttt{consistency\_prob\_one\_rate}); and for $0\le r\le 1$,
$0\le\mathrm{consistencyProbability}\,r\,c\le 1$
(\texttt{consistency\_prob\_nonneg}, \texttt{consistency\_prob\_le\_one}).
\end{theorem}

\begin{theorem}[\texttt{overlap\_quadratic\_growth}]
$\mathrm{overlapConstraintCount}\,n\,\mathit{nRows}\,\mathit{nCols} \le n\cdot
n\cdot(\mathit{nRows}\cdot\mathit{nCols})$.
\end{theorem}
\begin{proof}
$\tfrac{n(n-1)}{2}\le n(n-1)\le n\cdot n$.
\end{proof}

\begin{theorem}[\texttt{overlap\_zero\_of\_lt\_two}]
For $n<2$, $\mathrm{overlapConstraintCount}\,n\,\mathit{nRows}\,\mathit{nCols}=0$.
\end{theorem}

\begin{conjecture}[\texttt{conjecture\_exponential\_decay\_testable}]
For all $n,k$ and $r$ with $0<r<1$, $2\le n$, $1\le k$,
\[
\mathrm{consistencyProbability}\,r\,(\mathrm{overlapConstraintCount}\,n\,k\,n)
< \mathrm{consistencyProbability}\,r\,(k\cdot n).
\]
\end{conjecture}
\begin{remark}
The quadratic-count probability lies strictly below the linear-count
probability. For $n=10$, $k=100$, $r=0.3$, the count is
$\tfrac{n(n-1)}{2}\cdot k=4500$, so $P\approx 0.7^{4500}\approx 10^{-697}$:
large noisy databases are essentially never spontaneously consistent.
\end{remark}

\section{Sheaf Filtrations: Progressive Imputation}

\begin{theorem}[\texttt{sheaf\_filtration\_auto\_consistent}]
If $\mathrm{levels}:\mathrm{Fin}\,d\to\mathrm{PartialDB}$ is monotone
($\forall i\le j,\forall p\,v,\ \mathrm{levels}\,i\,p=\some\,v\to
\mathrm{levels}\,j\,p=\some\,v$), then $\mathrm{SheafCondition}(\mathrm{levels})$.
\end{theorem}
\begin{proof}
Given $\mathrm{levels}\,i\,p=\some\,v_1$ and $\mathrm{levels}\,j\,p=\some\,v_2$,
compare $i,j$ and push the smaller forward by monotonicity to force
$v_1=v_2$.
\end{proof}

\begin{theorem}[\texttt{sheaf\_filtration\_exists\_singleton}]
Every partial database is the unique level of a depth-$1$ sheaf filtration.
\end{theorem}

\begin{theorem}[\texttt{filtration\_final\_contains\_all}]
In any sheaf filtration of positive depth, for every level $i$,
$\dom(F.\mathrm{level}\,i)\subseteq\dom(F.\mathrm{level}\,\langle d-1\rangle)$.
\end{theorem}
\begin{proof}
A cell filled at level $i$ stays filled at the final index by monotonicity.
\end{proof}

\section{Applications}
Multi-source record linkage (incremental merge licensed by
\texttt{gluing\_preserves\_consistency}; feasibility certified by
\texttt{coboundary\_zero\_iff\_sheaf}); constraint-aware imputation targeting
zero objective (\texttt{imputation\_zero\_iff\_extends}); feasibility triage via
the $(1-r)^C$ calculus and quadratic constraint growth; and append-only
streaming imputation modeled by \texttt{SheafFiltration}.

\section{Discussion}
The function sheaf has honest functions as sections, so pairwise compatibility
suffices ($H^1=0$); this makes \texttt{coboundary\_zero\_iff\_sheaf} an exact
computable criterion but excludes quotient/torsor stalks where a nontrivial
$\check H^1$ obstructs gluing. The independence behind $(1-r)^C$ is a modeling
choice best read through its algebraic laws.

\section{Future Directions}
(1) \v Cech obstruction for value-quotient sheaves (nonzero $\check H^1$ as a
non-gluing certificate). (2) An exact-imputability phase transition $r^*(k)$ via
moment methods on $(1-r)^C\cdot(\#\text{configs})$. (3) Strict dominance of
sheaf imputation when $H^1=0$ (unique zero-error completion vs.\ overlap-variance
lower bound for mean/KNN, $r<1/2$). (4) Optimality of the quadratic constraint
count: $\Omega(k^2)$ checks for any restriction-closed scheme.

\section{Conclusion}
Renaming ``database with missing entries'' as ``partial section of the function
sheaf'' yields a rigorous theory: gluing preserves and accumulates
observations, conflict-count-zero is exactly the sheaf condition, faithful
imputation is exactly zero-cost imputation, accidental consistency decays
exponentially in a quadratically growing constraint count, and monotone
imputation is contradiction-free by construction.

