from __future__ import annotations
from typing import Dict, List, Optional, Tuple

Pos = Tuple[int, int]
PartialDB = Dict[Pos, Optional[int]]

def coboundary_norm(views, positions):
    t = 0
    for i in range(len(views)):
        for j in range(len(views)):
            for p in positions:
                vi, vj = views[i].get(p), views[j].get(p)
                if vi is not None and vj is not None and vi != vj:
                    t += 1
    return t

def sheaf_condition(views, positions):
    for i in range(len(views)):
        for j in range(len(views)):
            for p in positions:
                vi, vj = views[i].get(p), views[j].get(p)
                if vi is not None and vj is not None and vi != vj:
                    return False
    return True

def glue_two(a, b, positions):
    out = {}
    for p in positions:
        va = a.get(p)
        out[p] = va if va is not None else b.get(p)
    return out

# Three consistent local views of a 2x2 table, plus a conflicting variant.
positions = [(r, c) for r in range(2) for c in range(2)]
a = {(0, 0): 7, (0, 1): 3}
b = {(0, 1): 3, (1, 0): 5}
c = {(1, 0): 5, (1, 1): 9}
fam = [a, b, c]
print("coboundary norm =", coboundary_norm(fam, positions))
print("sheaf holds    =", sheaf_condition(fam, positions))
assert (coboundary_norm(fam, positions) == 0) == sheaf_condition(fam, positions)
glued = glue_two(a, b, positions)
assert all(glued[p] == v for p, v in a.items())
assert all(glued[p] == v for p, v in b.items())
print("glue extends both views ->", {p: v for p, v in glued.items() if v is not None})

b_bad = {(0, 1): 99, (1, 0): 5}
print("conflicting coboundary norm =", coboundary_norm([a, b_bad, c], positions))
assert not sheaf_condition([a, b_bad, c], positions)
print("coboundary_zero_iff_sheaf demonstrated")

